return function(Lib,Core)local N,C="Combat",""local U32=4294967296 local NX={}for a=0,15 do for b=0,15 do local r,x,y,p,t=0,a,b,1,0 while t<4 do local xb,yb=x%2,y%2 if xb~=yb then r=r+p end x=(x-xb)/2 y=(y-yb)/2 p=p*2 t=t+1 end NX[a*16+b]=r end end local function bxb(a,b)return NX[((a-a%16)/16)*16+(b-b%16)/16]*16+NX[(a%16)*16+(b%16)]end local function bxor(a,b)a=a%U32 b=b%U32 local r,m,t=0,1,0 while t<4 do local ab,bb=a%256,b%256 r=r+bxb(ab,bb)*m a=(a-ab)/256 b=(b-bb)/256 m=m*256 t=t+1 end return r end local function mul32(a,b)a=a%U32 b=b%U32 local ah=(a-a%65536)/65536 local al=a%65536 return(((ah*b)%65536)*65536+al*b)%U32 end local function shr(x,n)local d,k=1,0 while k<n do d=d*2 k=k+1 end return(x-(x%d))/d end local function rotl(x,n)x=x%U32 local pw,k=1,0 while k<n do pw=pw*2 k=k+1 end local lf=mul32(x,pw)local dp,k2=1,0 while k2<(32-n)do dp=dp*2 k2=k2+1 end return(lf+(x-(x%dp))/dp)%U32 end local function chash(s,sd)local h=(2166136261+(sd or 0))%U32 local ac=5381 local i,n=1,#s while i<=n do local c=s:byte(i)h=bxor(h,c)h=mul32(h,16777619)ac=(mul32(ac,33)+c+i)%U32 h=bxor(h,rotl(ac,(c%23)+1))h=rotl(h,(i%13)+3)i=i+1 end h=bxor(h,shr(h,16))h=mul32(h,2246822519)h=bxor(h,shr(h,13))h=mul32(h,3266489917)h=bxor(h,shr(h,16))return h end local HEX="0123456789abcdef"local function tohex(v)local s,i="",0 while i<8 do local nb=v%16 v=(v-nb)/16 s=HEX:sub(nb+1,nb+1)..s i=i+1 end return s end local function dk(m,n)local base=m.."\0"..n.."\0syllinse"local k,round="",0 while round<8 do k=k..tohex(chash(base.."|"..round,mul32(round,2654435761)))round=round+1 end return k end local function ks(key,length)local s=chash(key,0)if s==0 then s=2654435761 end local out,pd={},0 while pd<length do s=bxor(s,mul32(s,8192))s=bxor(s,(s-s%131072)/131072)s=bxor(s,mul32(s,32))s=s%U32 local t=s local b1=t%256 t=(t-b1)/256 local b2=t%256 t=(t-b2)/256 local b3=t%256 t=(t-b3)/256 local b4=t pd=pd+1 out[pd]=b1 if pd>=length then break end pd=pd+1 out[pd]=b2 if pd>=length then break end pd=pd+1 out[pd]